//  CounterExampleUITests.swift
//  CounterExampleUITests
//
//  Drives the real CounterExample app via the Accessibility API. Run via
//  the CounterExample.xcodeproj scheme (generated by `xcodegen generate`
//  from project.yml) -- Xcode wires this bundle to the CounterExample app
//  target automatically (TEST_TARGET_NAME in project.yml), so
//  XCUIApplication() launches it with no extra setup:
//
//      xcodegen generate
//      xcodebuild -project CounterExample.xcodeproj -scheme CounterExample \
//          -destination 'platform=macOS' test -only-testing:CounterExampleUITests
//
//  Requires the test runner to have Accessibility permission (System
//  Settings > Privacy & Security > Accessibility) for XCUIApplication to
//  control other processes.

import XCTest

final class CounterExampleUITests: XCTestCase {
    var app: XCUIApplication!

    override func setUpWithError() throws {
        continueAfterFailure = false
        app = XCUIApplication()
        app.launch()
    }

    override func tearDownWithError() throws {
        app?.terminate()
    }

    /// SwiftUI's `Text` exposes its content as the accessibility *value*, not the
    /// *label*, on macOS -- `staticTexts["countLabel"].label` is always empty.
    private var countLabelValue: String {
        app.staticTexts["countLabel"].value as? String ?? ""
    }

    func testInitialCountIsZero() throws {
        XCTAssertEqual(countLabelValue, "Count: 0")
    }

    func testIncrementIncreasesCount() throws {
        app.buttons["incrementButton"].click()
        XCTAssertEqual(countLabelValue, "Count: 1")
    }

    func testDecrementDecreasesCount() throws {
        app.buttons["decrementButton"].click()
        XCTAssertEqual(countLabelValue, "Count: -1")
    }

    func testResetReturnsToZero() throws {
        app.buttons["incrementButton"].click()
        app.buttons["incrementButton"].click()
        app.buttons["resetButton"].click()
        XCTAssertEqual(countLabelValue, "Count: 0")
    }

    func testMultipleOperations() throws {
        app.buttons["incrementButton"].click() // 1
        app.buttons["incrementButton"].click() // 2
        app.buttons["decrementButton"].click() // 1
        XCTAssertEqual(countLabelValue, "Count: 1")
    }
}
